-- Настройки прайса: цены в $, налог 15% (меняется в «Sozlamalar»), схемы скидок 1/3/5% с маржой 37%
insert into public.app_settings (key, value) values ('price_currency', '"$"'::jsonb) on conflict (key) do update set value = excluded.value;
insert into public.app_settings (key, value) values ('result_currency', '"so''m"'::jsonb) on conflict (key) do update set value = excluded.value;
insert into public.app_settings (key, value) values ('tax_name', '"QQS"'::jsonb) on conflict (key) do update set value = excluded.value;
insert into public.app_settings (key, value) values ('tax_pct', '15'::jsonb) on conflict (key) do update set value = excluded.value;
insert into public.app_settings (key, value) values ('finance_schemes', '[{"id":"d1","name":"Chegirma 1%","discount":1,"margin":37,"margin_work":37},{"id":"d3","name":"Chegirma 3%","discount":3,"margin":37,"margin_work":37},{"id":"d5","name":"Chegirma 5%","discount":5,"margin":37,"margin_work":37}]'::jsonb) on conflict (key) do update set value = excluded.value;
